// Measures the profile generated by :baselineprofile against the app's release-like benchmarkRelease (#312).
plugins {
    id("com.android.test")
    // Creates benchmarkRelease (and the target app wiring) from the release build type.
    id("androidx.baselineprofile")
}

android {
    namespace = "io.github.mateuxlucax.caparao.macrobenchmark"
    compileSdk = 37

    defaultConfig {
        minSdk = 31
        targetSdk = 37
        testInstrumentationRunner = "androidx.test.runner.AndroidJUnitRunner"
        // #312 runs the benchmarks on the emulator: the numbers are the tool's baseline, not a device comparison.
        testInstrumentationRunnerArguments["androidx.benchmark.suppressErrors"] = "EMULATOR"
    }

    targetProjectPath = ":app"

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
}

dependencies {
    implementation("androidx.test:runner:1.7.0")
    implementation("androidx.test.ext:junit:1.3.0")
    implementation("androidx.test.uiautomator:uiautomator:2.4.1")
    implementation("androidx.benchmark:benchmark-macro-junit4:1.5.0")
}
